+            let _ = sender.send(());
+        });
+        assert!(child.wait().unwrap().success());
+        assert!(receiver.recv_timeout(Duration::from_millis(200)).is_err());
+        job.kill();
+        receiver.recv_timeout(Duration::from_secs(5)).unwrap();
+    }
+}

